  function sheetShell(title,copy,content){return'<div class="sheet-backdrop" data-action="close-sheet"><section class="sheet" data-sheet-surface role="dialog" aria-modal="true"><div class="sheet-handle"></div><div class="cluster between"><div><h2 class="sheet-title">'+h(title)+'</h2><p class="supporting">'+h(copy||"")+'</p></div><button class="icon-button flat" data-action="close-sheet">'+icon("close")+'</button></div><div style="margin-top:20px">'+content+'</div></section></div>'}
  function renderSheet(){const sig=state.sheet?JSON.stringify(state.sheet):"";if(sig===state.lastSheetSignature)return;state.lastSheetSignature=sig;if(!state.sheet){sheetRegion.innerHTML="";return}if(state.sheet.type==="availability")sheetRegion.innerHTML=availabilitySheet();else if(state.sheet.type==="bill"){const bo=state.orders&&state.orders.find?state.orders.find(x=>x.id===state.sheet.orderId):null;sheetRegion.innerHTML=bo?sheetShell("Order bill","Your earnings on this order at Scraveit's rates.",'<div class="bill-paper">'+billMarkup(bo)+'</div><button class="button primary full" style="margin-top:16px" data-action="print-bill" data-order-id="'+h(bo.id)+'">Print or save as PDF</button>'):""}else if(state.sheet.type==="offer")sheetRegion.innerHTML=offerSheet(state.sheet);else if(state.sheet.type==="menu")sheetRegion.innerHTML=menuSheet(state.sheet.item);else if(state.sheet.type==="deleteMenu")sheetRegion.innerHTML=sheetShell("Delete menu item?","This cannot be undone.",'<div class="stack"><div class="notice danger">'+icon("warning","small")+'<span>Archive the item if it may return later.</span></div><button class="button danger full" data-action="confirm-delete-menu-item" data-item-id="'+h(state.sheet.itemId)+'">Delete permanently</button><button class="button tonal full" data-action="close-sheet">Keep item</button></div>');else if(state.sheet.type==="invite")sheetRegion.innerHTML=inviteSheet();else if(state.sheet.type==="decline")sheetRegion.innerHTML=declineSheet(order(state.sheet.orderId));else sheetRegion.innerHTML=""}
