  function openGoogleSignIn(){if(window.FeastlyRestaurantNative&&FeastlyRestaurantNative.signInWithGoogle){state.loading=true;render({preserve:true});FeastlyRestaurantNative.signInWithGoogle()}else if(window.SavrivoCloudNative&&SavrivoCloudNative.requestGoogleSignIn){state.loading=true;render({preserve:true});SavrivoCloudNative.requestGoogleSignIn()}else toast("Google Sign-In is available in the installed Android app.","danger")}
  async function completeGoogleSignIn(tokenType,token){try{const credential=tokenType==="id_token"?firebase.auth.GoogleAuthProvider.credential(token):firebase.auth.GoogleAuthProvider.credential(null,token);const result=await fbAuth.signInWithCredential(credential);applyAuthUser(result.user);try{await resolveMember();await sync(true);startRealtime();registerNativePush().catch(()=>{});state.route="dashboard";routeToPendingOrderIfIdle();toast("Restaurant workspace ready.","success")}catch(err){const appSnap=await restaurantApplicationDoc(state.session.uid).get().catch(()=>null),appRec=appSnap&&appSnap.exists?appSnap.data():null;if(appRec){state.application=appRec;state.route="pending";toast("Your registration is pending Admin review.","warning")}else{state.googleSignup={email:result.user.email||"",name:result.user.displayName||""};state.authTab="signup";state.route="login";toast("Signed in. Add your store details to register.","success")}}}catch(e){state.session=null;state.member=null;localStorage.removeItem("savrivo.restaurant.session");toast(friendly(e),"danger")}finally{state.loading=false;render()}}
  window.googleIdTokenReceived=function(idToken){return completeGoogleSignIn("id_token",idToken)};
  window.googleAccessTokenReceived=function(accessToken){return completeGoogleSignIn("access_token",accessToken)};
  window.googleSignInFailed=function(message){state.loading=false;toast(message||"Google sign-in failed.","danger");render({preserve:true})};
  async function handleClick(event){const c=event.target.closest("[data-action]");if(!c)return;const a=c.dataset.action;if(a==="google-signin"){openGoogleSignIn();return}if(a==="switch-auth-tab"){state.authTab=c.dataset.tab;render();return}if(a==="register-this-kind"){state.googleSignup={email:state.session&&state.session.email||"",name:state.session&&state.session.name||""};state.member=null;state.restaurant=null;state.memberships={};try{localStorage.removeItem("savrivo.restaurant.memberCache");localStorage.removeItem("savrivo.restaurant.selectedRestaurantId")}catch(_){}state.authTab="signup";state.route="login";render();return}if(a==="check-approval"){checkApprovalStatus();return}if(a==="close-sheet"){if(c.classList.contains("sheet-backdrop")&&event.target.closest("[data-sheet-surface]"))return;closeSheet();return}if(a==="go"){go(c.dataset.route);return}if(a==="back"){back();return}if(a==="open-bill"){state.sheet={type:"bill",orderId:c.dataset.orderId};renderSheet();return}if(a==="print-bill"){const bo=state.orders.find(x=>x.id===c.dataset.orderId);if(bo)printBill(bo);return}if(a==="refresh"){state.loading=true;render({preserve:true});sync(true).then(()=>toast("Restaurant refreshed.","success")).catch(()=>{}).finally(()=>{state.loading=false;render({preserve:true})});return}if(a==="refresh-settlement"){loadSettlementSummary(true).then(()=>{if(!state.settlementError)toast("Settlement summary refreshed.","success")});return}if(a==="open-order"){go("order",{orderId:c.dataset.orderId});return}if(a==="switch-restaurant"){switchRestaurant(c.dataset.restaurantId);return}if(a==="open-chat"){const o=order(c.dataset.orderId);if(o)openChat(o,c.dataset.channel,c.dataset.channel==="customerRestaurant"?"Chat with customer":"Chat with rider");return}if(a==="advance-order"){advanceOrder(order(c.dataset.orderId),c.dataset.status);return}if(a==="decline-order"){setSheet({type:"decline",orderId:c.dataset.orderId});return}if(a==="availability"){if(state.restaurant&&state.restaurant.open!==false)setSheet({type:"availability"});else setAvailability(true);return}if(a==="set-offline"){setAvailability(false,c.dataset.minutes);return}if(a==="new-menu-item"){setSheet({type:"menu",item:null});return}if(a==="edit-menu-item"){setSheet({type:"menu",item:state.menus[c.dataset.itemId]||menuItems().find(i=>i.id===c.dataset.itemId)||null});return}if(a==="archive-menu-item"){archiveMenu(c.dataset.itemId);return}if(a==="detect-location"){if(window.FeastlyRestaurantNative&&FeastlyRestaurantNative.requestRestaurantLocation)FeastlyRestaurantNative.requestRestaurantLocation();else toast("Location detection is available in the installed app.","danger");return}if(a==="map-zoom"){state.mapZoom=Math.max(4,Math.min(19,state.mapZoom+Number(c.dataset.delta||0)));render({preserve:true});return}if(a==="map-pick"){const rect=c.getBoundingClientRect(),cx=Number(c.dataset.centerX),cy=Number(c.dataset.centerY),z=Number(c.dataset.zoom),x=cx+(event.clientX-rect.left-rect.width/2),y=cy+(event.clientY-rect.top-rect.height/2),ll=pixelLatLng(x,y,z);state.mapDraft=ll;render({preserve:true});return}if(a==="staff"){go("staff");return}if(a==="new-offer"){setSheet({type:"offer",id:""});setTimeout(refreshOfferPreview,0);return}if(a==="edit-offer"){setSheet({type:"offer",id:c.dataset.offerId});setTimeout(refreshOfferPreview,0);return}if(a==="invite-staff"){setSheet({type:"invite"});return}if(a==="logout"){finishLogout();return}}
  async function handleSubmit(event){event.preventDefault();const form=event.target;if(!(form instanceof HTMLFormElement))return;if(form.id==="offer-form"){saveOffer(form);return}if(form.id==="signup-form"){if(state.loading)return;const fd=new FormData(form);state.loading=true;render();try{const viaGoogle=!!(state.googleSignup&&state.session),email=viaGoogle?String(state.googleSignup.email||"").toLowerCase():String(fd.get("email")||"").trim().toLowerCase(),password=viaGoogle?"google":String(fd.get("password")||""),restaurantName=String(fd.get("restaurantName")||"").trim(),ownerName=String(fd.get("ownerName")||"").trim(),phone=String(fd.get("phone")||"").trim(),city=String(fd.get("city")||"").trim(),address=String(fd.get("address")||"").trim(),cuisines=String(fd.get("cuisines")||"Desserts").split(",").map(x=>x.trim()).filter(Boolean);if(!email||!password||!restaurantName||!ownerName||!phone||!city||!address){toast("Please fill in all required registration fields.","danger");return}if(!viaGoogle){const cred=await fbAuth.createUserWithEmailAndPassword(email,password);applyAuthUser(cred.user)}state.googleSignup=null;const appRec={id:state.session.uid,uid:state.session.uid,email,ownerName,restaurantName,storeType:STORE.type,phone,city,address,cuisines,status:"submitted",submittedAt:Date.now()};await restaurantApplicationDoc(state.session.uid).set(appRec);state.application=appRec;state.route="pending";toast("Restaurant registration submitted for Admin review.","success")}catch(e){toast("Registration failed: "+friendly(e),"danger")}finally{state.loading=false;render()}return}if(form.id==="login-form"){if(state.loading)return;const fd=new FormData(form);state.loading=true;render();try{const email=String(fd.get("email")||"").trim().toLowerCase(),password=String(fd.get("password")||"");const cred=await fbAuth.signInWithEmailAndPassword(email,password);applyAuthUser(cred.user);try{await resolveMember();await sync(true);startRealtime();registerNativePush().catch(()=>{});state.route="dashboard";routeToPendingOrderIfIdle();toast("Restaurant workspace ready.","success")}catch(err){const appSnap=await restaurantApplicationDoc(state.session.uid).get().catch(()=>null),appRec=appSnap&&appSnap.exists?appSnap.data():null;if(appRec){state.application=appRec;state.route="pending";toast("Your registration is pending Admin review.","warning")}else throw err}}catch(e){state.session=null;state.member=null;localStorage.removeItem("savrivo.restaurant.session");toast("Sign in failed: "+friendly(e),"danger")}finally{state.loading=false;render()}return}if(form.id==="menu-form"){saveMenu(form);return}if(form.id==="profile-form"){saveProfile(form);return}if(form.id==="invite-form"){inviteStaff(form);return}if(form.id==="decline-form"){declineOrder(form);return}if(form.id==="chat-form"){sendChat(form);return}}
  function bootstrap(){window.addEventListener("online",()=>{state.network=true;triggerForegroundResync(true)});window.addEventListener("offline",()=>{state.network=false;render()});document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")triggerForegroundResync(false)});window.addEventListener("focus",()=>triggerForegroundResync(false));window.addEventListener("pageshow",()=>triggerForegroundResync(false));document.addEventListener("click",handleMenuCrudClick,true);document.addEventListener("click",handleClick);document.addEventListener("submit",handleSubmit);document.addEventListener("input",event=>{if(event.target&&event.target.form&&event.target.form.id==="offer-form")refreshOfferPreview();if(event.target&&event.target.id==="menu-search"){state.menuQuery=event.target.value;const node=document.getElementById("menu-results");if(node)node.innerHTML=menuResultsMarkup()}});if(!state.session){state.route="login";render();return Promise.resolve()}state.loading=true;
    // Cache-first: state.member was restored from localStorage above when this device has
    // logged in as this restaurant before (see `member: load(...)` in the state literal), so
    // the real dashboard - with its own graceful handling of empty orders/restaurant fields -
    // renders immediately from that. The network calls below only refresh it now; they no
    // longer gate the first paint. A first-ever login on this device (no cached member yet)
    // still shows the spinner briefly, since there is nothing to show without first knowing
    // whether this account lands on the dashboard or a pending-application screen.
    state.route=state.member?"dashboard":"launch";render();
    return new Promise(resolve=>{const unsubscribe=fbAuth.onAuthStateChanged(authUser=>{unsubscribe();resolve(authUser)})}).then(authUser=>{if(!authUser)throw new Error("AUTH_REQUIRED");applyAuthUser(authUser);return resolveMember()}).then(()=>{save("savrivo.restaurant.memberCache",state.member);return sync(true)}).then(()=>{startRealtime();ensureNativePushRegistered(false);state.route="dashboard";routeToPendingOrderIfIdle()}).catch(async()=>{if(state.session&&state.session.uid){const appSnap=await restaurantApplicationDoc(state.session.uid).get().catch(()=>null),appRec=appSnap&&appSnap.exists?appSnap.data():null;if(appRec){state.application=appRec;state.route="pending";state.member=null;localStorage.removeItem("savrivo.restaurant.memberCache");return}}state.session=null;state.member=null;localStorage.removeItem("savrivo.restaurant.session");localStorage.removeItem("savrivo.restaurant.memberCache");state.route="login"}).finally(()=>{state.loading=false;render({preserve:true})})}
  bootstrap();
